def gen(rng):
    LIM = 2**31 - 1
    def ev(s):
        vals = []
        ops = []
        PREC = {'+': 1, '-': 1, '*': 2, '/': 2, 'u': 3, 'n': 3}
        def apply():
            op = ops.pop()
            if op == 'n':
                r = -vals.pop()
            elif op == 'u':
                return True
            else:
                b = vals.pop(); a = vals.pop()
                if op == '+': r = a + b
                elif op == '-': r = a - b
                elif op == '*': r = a * b
                else:
                    if b == 0:
                        return False
                    q = abs(a) // abs(b)
                    r = q if (a < 0) == (b < 0) else -q
            if abs(r) > LIM:
                return False
            vals.append(r)
            return True
        expect = True
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == ' ':
                i += 1
                continue
            if ch.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                vals.append(int(s[i:j]))
                i = j
                expect = False
                continue
            if ch == '(':
                ops.append('('); expect = True
            elif ch == ')':
                while ops[-1] != '(':
                    if not apply(): return None
                ops.pop(); expect = False
            elif expect and ch in '+-':
                ops.append('u' if ch == '+' else 'n')
            else:
                p = PREC[ch]
                while ops and ops[-1] != '(' and PREC[ops[-1]] >= p:
                    if not apply(): return None
                ops.append(ch); expect = True
            i += 1
        while ops:
            if not apply(): return None
        return vals[0]

    def build(target, maxlit, wts, popen, pclose, pun, psp, safe):
        out = []
        L = 0
        depth = 0
        prev_div = False
        def sp():
            return ' ' if rng.random() < psp else ''
        while True:
            nun = 0
            while True:
                if nun < 3 and rng.random() < pun:
                    piece = rng.choice('+-') + sp()
                    out.append(piece); L += len(piece); nun += 1
                    continue
                if not (safe and prev_div) and L < target and depth < 100 and rng.random() < popen:
                    piece = '(' + sp()
                    out.append(piece); L += len(piece); depth += 1
                    continue
                break
            lit = rng.randint(1 if safe else 0, maxlit)
            piece = str(lit)
            out.append(piece); L += len(piece)
            while depth > 0 and (L >= target or rng.random() < pclose):
                piece = sp() + ')'
                out.append(piece); L += len(piece); depth -= 1
            if L >= target and depth == 0:
                break
            op = rng.choices('+-*/', weights=wts)[0]
            piece = sp() + op + sp()
            out.append(piece); L += len(piece)
            prev_div = (op == '/')
        return ''.join(out)

    def valid(target, maxlit, wts, popen, pclose, pun, psp, safe):
        for attempt in range(60):
            s = build(target, maxlit, wts, popen, pclose, pun, psp, safe)
            if ev(s) is not None:
                return s
            if wts[2] > 0:
                wts = [wts[0], wts[1], wts[2] * 0.6, wts[3]]
        return '1+2'

    tests = ['5', '0', '  42  ', '1+2', '-7 + 5 * 8 - 5 / 4 + (5 + 4)', '2 * (3 - -4) / 5', '-(2 + 3) * 4 - 7 / -2',
             '--3', '+-3', '- - 3', '-(-(-(4)))', '7 / -2', '-7 / 2', '(((8)))', '1000000000 + 1000000000', '2147483647 - 2147483647',
             '10 / 3 * 3', '2 - 3 - 4', '100 / 10 / 5', '1 - (2 - (3 - 4))', '5 * -(3 + 2) / -4']
    for _ in range(30):
        n = rng.choice([5, 10, 20, 40, 80, 150, 300])
        tests.append(valid(n, rng.choice([5, 20, 1000, 10**9]), [3, 3, 2, 2], 0.2, 0.3, 0.1, 0.15, False))
    big = 99900
    tests.append(valid(big, 9, [4, 4, 2, 1], 0.12, 0.3, 0.05, 0.1, True))
    tests.append(valid(big, 9, [3, 3, 3, 3], 0.08, 0.3, 0.1, 0.0, True))
    tests.append(valid(big, 9, [5, 5, 0.3, 1], 0.2, 0.4, 0.15, 0.3, True))
    tests.append('+'.join(str(rng.randint(1, 9)) for _ in range(big // 2 - 1))[:big - 1])
    def seg_join(seg, joiner='+'):
        parts = []
        total = 0
        while total + len(seg) + 1 < 99800:
            parts.append(seg)
            total += len(seg) + 1
        return joiner.join(parts)
    d = 150
    tests.append(seg_join('(' * d + '1+2' + ')' * d))
    tests.append(seg_join('-(' * d + '7' + ')' * d))
    tests.append(seg_join(''.join('%d-(' % (i % 9 + 1) for i in range(d)) + '1' + ')' * d))
    tests.append('(' * 150 + '5' + ')' * 150)
    return tests
